function startRun(done=0){clearInterval(timer);state.running=true;state.cancelled=false;state.done=done;state.phase='designing';state.left='agent';state.page='editor';location.hash='editor';render();timer=setInterval(()=>{state.done++;if(state.done>=5){state.phase='validating';render();clearInterval(timer);timer=setTimeout(()=>{state.running=false;state.phase='completed';state.revision++;render();toast('模拟生成完成 · 可继续编辑或查看验证报告')},1000)}else render()},1800)}
