function bindProjectCards(){document.querySelectorAll('[data-project]').forEach(e=>{const open=()=>{const i=Number(e.dataset.project);state.project=['青禾生活 · 品牌官网','木序 · 家居生活','Flow · 团队工作台'][i];state.title=['把自然的松弛感，\n带回每一天','一件器物，\n一段生活。','从想法到行动，\n更有秩序。'][i];state.color=['#468b69','#9c8058','#476bcc'][i];state.cancelled=false;go('editor');toast('已打开示例项目；画布沿用同一原型模板')};e.onclick=open;e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();open()}}})}
